package net.civeira.phylax.feature.observe.observedalertrule.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ThresholdVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property threshold of observed alert rule ")
  void test_threshold_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> ThresholdVO.tryFrom(null));
    Assertions.assertEquals(1, ThresholdVO.from(1).getThreshold());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> ThresholdVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", ThresholdVO.from(1).toString());
  }
}
